SELECT  

    u.deleted = 0 AND tm.status = 1
    AND (u.real_name LIKE CONCAT('%', #{blurParam}, '%') OR u.username LIKE CONCAT('%', #{blurParam}, '%'))
    AND r.id = #{roleId}
    AND u.status = #{status}

SELECT u.id FROM tenant_user u
JOIN tenant_member tm ON tm.user_id = u.id AND tm.enterprise_id = #{enterpriseId}
    AND tm.deleted = 0 AND tm.status = 1
WHERE u.deleted = 0 AND u.status = 1
AND u.real_name = #{name}
AND u.email = #{email}
AND u.id_num = #{idNum}
ORDER BY u.id ASC LIMIT 1
